from fastapi import Depends, Security

def test_hashable():
    d1 = Depends(lambda: 1)
    d2 = Depends(lambda: 1)
    s1 = Security(lambda: 1, scopes=["admin"])
    s2 = Security(lambda: 1, scopes=["admin"])

    # These should be hashable now
    try:
        hash(d1)
        print("Depends is hashable")
    except TypeError as e:
        print(f"Depends is NOT hashable: {e}")

    try:
        hash(s1)
        print("Security is hashable")
    except TypeError as e:
        print(f"Security is NOT hashable: {e}")

    # Test if they can be used as keys in a dict
    try:
        d_dict = {d1: "value1"}
        print("Depends can be a dict key")
    except TypeError as e:
        print(f"Depends cannot be a dict key: {e}")

    try:
        s_dict = {s1: "value2"}
        print("Security can be a dict key")
    except TypeError as e:
        print(f"Security cannot be a dict key: {e}")

if __name__ == "__main__":
    test_hashable()

